function calcEMA(arr, period) {
  if (arr.length < period) return arr[arr.length-1].price;
  const k = 2 / (period + 1);
  let ema = arr.slice(0, period).reduce((s,p) => s + p.price, 0) / period;
  for (let i = period; i < arr.length; i++)
    ema = (arr[i].price - ema) * k + ema;
  return ema;
}

function calcRSI(arr, period = 14) {
  if (arr.length < period + 1) return 50;
  let gains = 0, losses = 0;
  for (let i = arr.length - period; i < arr.length; i++) {
    const chg = arr[i].price - arr[i-1].price;
    if (chg > 0) gains += chg; else losses += Math.abs(chg);
  }
  const rs = (gains/period) / (losses/period || 0.001);
  return 100 - (100 / (1 + rs));
}

